import math

def solve_search(p, max_a, max_b):
    solutions = []

    # Iterate over a and b respecting a <= b
    for a in range(1, max_a + 1):
        for b in range(a, max_b + 1):

            # Condition 1: a^(p-1) + b = p^x
            LHS1 = a**(p-1) + b

            # Check if LHS1 is a power of p
            x = 0
            temp1 = LHS1
            is_power1 = False
            if temp1 <= 0:
                continue
            while temp1 > 0:
                if temp1 % p != 0:
                    break
                temp1 //= p
                x += 1
            if temp1 == 1 and x >= 1:
                # LHS1 is p^x

                # Condition 2: b^(p-1) + a = p^y
                LHS2 = b**(p-1) + a

                # Check if LHS2 is a power of p
                y = 0
                temp2 = LHS2
                is_power2 = False
                if temp2 <= 0:
                    continue
                while temp2 > 0:
                    if temp2 % p != 0:
                        break
                    temp2 //= p
                    y += 1
                if temp2 == 1 and y >= 1:
                    # LHS2 is p^y
                    solutions.append(((p, a, b), (x, y)))
    return solutions

# --- Search for p = 3 ---
p3_solutions = solve_search(p=3, max_a=10, max_b=10)

# --- Search for p = 5 ---
p5_solutions = solve_search(p=5, max_a=5, max_b=5)

print("--- p=3 Solutions (a <= b <= 10) ---")
if p3_solutions:
    for ((p, a, b), (x, y)) in p3_solutions:
        print(f"Found: p={p}, a={a}, b={b}, (x, y)=({x}, {y})")
else:
    print("No solutions found for p=3 in the range.")

